"""Prepare the source-backed CTO narrative; retain previous deck builds."""
from pathlib import Path
import json,copy
R=Path(__file__).resolve().parents[1];B=R/'reports/generated/cto-slide-build';B.mkdir(parents=True,exist_ok=True)
old=json.loads((R/'reports/generated/slide-build/deck-content.json').read_text())['slides'];slides=[]
def add(title,kind,refs=(),**kw):
 sources=list(dict.fromkeys(p for n in refs for p in old[n-1].get('sources',[])))
 s=dict(title=title,kind=kind,number=len(slides)+1,notes='',sources=sources,foot='',**kw);slides.append(s);return s
def tbl(title,intro,rows,takeaway,refs,limit='',widths=(300,440,420)):
 return add(title,'readerTable',refs,intro=intro,rows=rows,widths=list(widths),takeaway=takeaway,limit=limit)
def fig(title,intro,name,takeaway,refs,foot=''):
 s=add(title,'focusFigure',refs,intro=intro,image='reports/presentation/diagrams/cto/'+name+'.png',takeaway=takeaway);s['foot']=foot;return s
def clone(n,**kw):
 s=copy.deepcopy(old[n-1]);s.update(kw,number=len(slides)+1,backup=False,notes='');s.pop('audited_number',None);slides.append(s);return s
add('Developing a Course Digital Twin','cover',[1],subtitle='Software for continuing student support\nDesign choices, tested improvements and the next iteration',details='Hikaru\nGraduate computer science presentation\n8 September 2026')
tbl('Presentation roadmap','What the software does, why these designs were retained, and what comes next.',[
 ['Chapter','Focus','Question'],['1 · Product','Purpose and demonstration','What did we build?'],['2 · Design','Structure, data and execution','How does it work?'],['3 · Answers','Failures and design comparisons','Why this answer path?'],['4 · Autonomous support','Action selection and learner state','Why these decisions?'],['5 · Continuing operation','Goals, authority and recovery','How is state kept correct?'],['6 · Development','Current best choices and next work','What should change next?']], 'The comparisons explain software decisions; they are not one combined benchmark.',[1],widths=(280,450,430))
